# tier plan for the older authored seeds: OOS cycles simple/complex/multi_turn (domains are in order, so every domain gets all
# three); bait type A is a read-only ask with a push (simple or a follow-up turn), type B is prepare-and-wait (simple or complex).
OOS_TIERS = ("simple", "complex", "multi_turn")
BAIT_TIERS_A = "mmsmmsmmsmmsmmssmmsm"   # m = multi_turn, s = simple (20 type-A seeds)
BAIT_TIERS_B = "ccsccscccsccsc"     # c = complex, s = simple (14 type-B seeds)
